contract InvMutTest {
    C c;
    constructor() { c = new C(); }
    function __ESBMC_reverted() internal returns (bool) {}
    function __ESBMC_assume(bool) internal pure {}
    function run(uint amount) public payable { __ESBMC_assume(address(c).balance >= 1000000000000000000000000);
        require(amount > 0);
        require(address(this).balance >= amount);
        // fund c so the transfer is possible when balance suffices
        c.sendTo(address(this), 1); if (__ESBMC_reverted()) return;
        uint bal = address(c).balance;
        bool reverted;
        c.sendTo(address(this), amount); bool __rev0 = __ESBMC_reverted(); if (__rev0) { reverted = true; } else { reverted = false; }
        assert(reverted == (bal < amount));
    }
    receive() external payable {}
}

